package com.smartseating.ui;

import com.smartseating.dao.DepartmentDAO;
import com.smartseating.model.*;
import com.smartseating.service.PrintService;
import com.smartseating.util.*;
import javax.swing.*;
import javax.swing.table.DefaultTableModel;
import java.awt.*;

public class DepartmentFrame extends AppFrame {
    private final DepartmentDAO dao=new DepartmentDAO();private final JTextField code=new JTextField(),name=new JTextField();private final JComboBox<String> status=new JComboBox<>(new String[]{"ACTIVE","INACTIVE"});private final JTable table=new JTable();private Department selected;
    public DepartmentFrame(User user){super("Department Management",user);UI.frame(this,900,590);build();refresh();}
    private void build(){content.add(title("Department Management"),BorderLayout.NORTH);JPanel form=UI.formPanel();UI.addField(form,0,"Department Code",code);UI.addField(form,1,"Department Name",name);UI.addField(form,2,"Status",status);JPanel a=new JPanel(new GridLayout(2,3,7,7));a.setOpaque(false);JButton add=button("ADD",UI.TEAL),update=button("UPDATE",UI.BLUE),del=button("DELETE",new Color(190,66,66)),clear=button("CLEAR",UI.MUTED),print=button("PRINT",UI.ORANGE);for(JButton b:new JButton[]{add,update,del,clear,print})a.add(b);GridBagConstraints g=new GridBagConstraints();g.gridx=0;g.gridy=3;g.gridwidth=2;g.fill=GridBagConstraints.HORIZONTAL;g.insets=new Insets(14,6,6,6);form.add(a,g);content.add(white(form),BorderLayout.WEST);UI.tableStyle(table);content.add(white(UI.scroll(table)),BorderLayout.CENTER);add.addActionListener(e->save());update.addActionListener(e->update());del.addActionListener(e->delete());clear.addActionListener(e->clear());print.addActionListener(e->PrintService.print("Department List",text()));table.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()&&table.getSelectedRow()>=0)load();});if("TEACHER".equals(currentUser.getRole())){add.setEnabled(false);update.setEnabled(false);del.setEnabled(false);}}
    private Department read(){return new Department(0,Validation.text(code.getText(),"Department code").toUpperCase(),Validation.text(name.getText(),"Department name"),(String)status.getSelectedItem());}
    private void save(){try{dao.save(read());clear();refresh();}catch(Exception ex){error(ex);}}private void update(){try{if(selected==null)throw new IllegalArgumentException("Select a department first.");Department d=read();d.setId(selected.getId());dao.update(d);clear();refresh();}catch(Exception ex){error(ex);}}private void delete(){try{if(selected==null)throw new IllegalArgumentException("Select a department first.");if(confirm("Delete selected department? Students using it must be removed first.")){dao.delete(selected.getId());clear();refresh();}}catch(Exception ex){error(ex);}}private void load(){int r=table.getSelectedRow();selected=new Department((int)table.getValueAt(r,0),String.valueOf(table.getValueAt(r,1)),String.valueOf(table.getValueAt(r,2)),String.valueOf(table.getValueAt(r,3)));code.setText(selected.getCode());name.setText(selected.getName());status.setSelectedItem(selected.getStatus());}private void clear(){selected=null;code.setText("");name.setText("");table.clearSelection();}private void refresh(){try{DefaultTableModel m=new DefaultTableModel(new Object[]{"ID","Code","Department Name","Status"},0);for(Department d:dao.findAll())m.addRow(new Object[]{d.getId(),d.getCode(),d.getName(),d.getStatus()});table.setModel(m);UI.tableStyle(table);}catch(Exception ex){error(ex);}}private String text(){StringBuilder b=new StringBuilder("DEPARTMENT LIST\n\n");for(int i=0;i<table.getRowCount();i++)b.append(table.getValueAt(i,1)).append(" | ").append(table.getValueAt(i,2)).append(" | ").append(table.getValueAt(i,3)).append("\n");return b.toString();}
}
